-- 0045 pair visibility (Oct 28 2026; Owner approved 12:53 IST). STAGING FIRST. GENERATED by work/oct28/locks/gen_0045.py.
-- Lets a 2nd user (an AE) join the workspace without seeing anyone else's data. Model fixed by data type (no per-row toggle):
--   * app.pairings (workspace, sdr_uid, ae_uid, status requested|active|ended). Only an AE can request, only the named SDR can
--     accept, either side can end (takes effect on the next query). No table write grant for authenticated: the three
--     app.pair_* SECURITY DEFINER functions are the only write path, so nobody can create an active pairing alone.
--     app.memberships.role (role_t, already has 'sdr' and 'ae') is the role; memberships stays read-only to authenticated.
--   * SHARED (5): accounts (+ sdr_uid backfilled to the owner, ae_uid nullable), people, account_briefs,
--     account_stage_history, research. Owner side = sdr_uid / owner_uid. AE side = read only, only for accounts whose ae_uid is
--     the caller AND an active pairing (workspace, sdr_uid, caller) exists. people rows carry DM text and notes, so the AE gets
--     NO direct people policy: app.shared_people() returns a column-safe subset instead.
--   * PRIVATE (30): every other table with a workspace policy: owner_uid (backfilled to the owner) = caller only.
--   * Owner: every existing row gets his uid, and new rows from the worker / cron / service_role (no signed-in user) get it too
--     (owner_fill trigger), so is_owner() sees exactly what it saw before. ari_worker policies are untouched.
--   * ari_pref / ari_push_ack (0043) now also require owner_uid = caller for signed-in callers.
-- Locks: ONE short transaction per table (add column with constant default = metadata only, drop default, create trigger,
--   swap policies), lock_timeout 5s / statement_timeout 60s. Re-runnable; ledger row last, after the end state is checked.
-- Rollback: 0045_pair_visibility_rollback.sql (restores the 37 policies verbatim). Checks: test/checks_after_0045.sql.

-- ---------- precheck ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
do $$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '0043') then
    raise exception '0045 precheck: 0043 is not applied'; end if;
  if to_regprocedure('app.is_member(uuid)') is null or to_regprocedure('app.aal_ok()') is null or to_regprocedure('public.is_owner()') is null then
    raise exception '0045 precheck: needs app.is_member, app.aal_ok, is_owner'; end if;
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid where t.typname = 'role_t' and e.enumlabel = 'ae')
     or not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid where t.typname = 'role_t' and e.enumlabel = 'sdr') then
    raise exception '0045 precheck: app.role_t lacks sdr/ae'; end if;
  if (select count(*) from information_schema.columns where table_schema = 'public' and column_name = 'workspace_id'
        and table_name = any(array['account_briefs', 'account_stage_history', 'accounts', 'app_changes', 'app_config', 'app_usage', 'ari_notes', 'ari_prefs', 'attachments', 'book', 'brief', 'copy_guidance', 'decisions', 'draft_edits', 'draft_tags', 'emails', 'events', 'hygiene_findings', 'log_entries', 'messages', 'notifications', 'ops', 'people', 'plays', 'push_subscriptions', 'push_tokens', 'queue', 'replies', 'research', 'scan_heartbeat', 'sent_messages', 'targets', 'task_events', 'tasks', 'threads'])) <> 35 then
    raise exception '0045 precheck: a target table lacks workspace_id'; end if;
end $$;
commit;

-- ---------- pairings + helpers (no lock on any public table) ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
create table if not exists app.pairings (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references app.workspaces(id) on delete cascade,
  sdr_uid uuid not null,
  ae_uid uuid not null,
  status text not null default 'requested' check (status in ('requested', 'active', 'ended')),
  created_at timestamptz not null default now(),
  accepted_at timestamptz,
  ended_at timestamptz,
  check (sdr_uid <> ae_uid)
);
create unique index if not exists pairings_live_uidx on app.pairings (workspace_id, sdr_uid, ae_uid) where status <> 'ended';
alter table app.pairings enable row level security;
alter table app.pairings force row level security;
revoke all on app.pairings from public, anon, authenticated;
grant select on app.pairings to authenticated;
drop policy if exists pair_read on app.pairings;
create policy pair_read on app.pairings for select to authenticated
  using (((sdr_uid = (select auth.uid())) or (ae_uid = (select auth.uid()))) and (select app.is_member(workspace_id)));

-- caller is an active member, an AE with an ACTIVE pairing to this SDR in this workspace
create or replace function app.pair_active(ws uuid, sdr uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select app.aal_ok() and exists (
    select 1 from app.pairings p join app.memberships m on m.workspace_id = p.workspace_id and m.user_id = p.ae_uid
     where p.workspace_id = ws and p.sdr_uid = sdr and p.ae_uid = auth.uid() and p.status = 'active'
       and m.status = 'active' and m.role = 'ae')
$$;
-- AE asks an SDR to pair. Caller must be an active 'ae' member; the SDR an active 'sdr' member of the same workspace.
create or replace function app.pair_request(ws uuid, sdr uuid) returns uuid language plpgsql volatile security definer set search_path = '' as $$
declare pid uuid;
begin
  if not app.has_role(ws, array['ae']::app.role_t[]) then raise exception 'only an AE member can request a pairing' using errcode = '42501'; end if;
  if not exists (select 1 from app.memberships m where m.workspace_id = ws and m.user_id = sdr and m.status = 'active' and m.role = 'sdr') then
    raise exception 'that user is not an SDR in this workspace' using errcode = '42501'; end if;
  select id into pid from app.pairings where workspace_id = ws and sdr_uid = sdr and ae_uid = auth.uid() and status <> 'ended';
  if pid is null then
    insert into app.pairings (workspace_id, sdr_uid, ae_uid) values (ws, sdr, auth.uid()) returning id into pid;
  end if;
  return pid;
end $$;
-- the named SDR accepts (the gate)
create or replace function app.pair_accept(pid uuid) returns void language plpgsql volatile security definer set search_path = '' as $$
begin
  update app.pairings p set status = 'active', accepted_at = now()
   where p.id = pid and p.sdr_uid = auth.uid() and p.status = 'requested'
     and app.has_role(p.workspace_id, array['sdr']::app.role_t[]);
  if not found then raise exception 'no pending pairing request for you to accept' using errcode = '42501'; end if;
end $$;
-- either side ends it; visibility stops on the next query
create or replace function app.pair_end(pid uuid) returns void language plpgsql volatile security definer set search_path = '' as $$
begin
  update app.pairings p set status = 'ended', ended_at = now()
   where p.id = pid and (p.sdr_uid = auth.uid() or p.ae_uid = auth.uid()) and p.status <> 'ended' and app.aal_ok();
  if not found then raise exception 'no live pairing of yours with that id' using errcode = '42501'; end if;
end $$;
-- fills owner_uid / sdr_uid on insert when not given: the signed-in user, else (worker, cron, service_role) the account's SDR
-- for shared child rows, else the workspace owner. BEFORE trigger, so it runs before NOT NULL and the RLS WITH CHECK.
create or replace function app.owner_fill() returns trigger language plpgsql security definer set search_path = '' as $$
declare acc uuid; s uuid;
begin
  if new.owner_uid is null then
    if coalesce(auth.role(), '') = 'authenticated' and auth.uid() is not null then
      new.owner_uid := auth.uid();
    else
      if tg_nargs > 0 and tg_argv[0] = 'child' then
        acc := nullif(to_jsonb(new) ->> 'account_id', '')::uuid;
        if acc is not null then select a.sdr_uid into s from public.accounts a where a.id = acc; end if;
      end if;
      new.owner_uid := coalesce(s, 'b14d1605-c766-4684-9a5b-71ffcab6967b'::uuid);
    end if;
  end if;
  return new;
end $$;
create or replace function app.sdr_fill() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.sdr_uid is null then
    new.sdr_uid := case when coalesce(auth.role(), '') = 'authenticated' and auth.uid() is not null then auth.uid()
                        else 'b14d1605-c766-4684-9a5b-71ffcab6967b'::uuid end;
  end if;
  return new;
end $$;

revoke all on function app.pair_active(uuid, uuid), app.pair_request(uuid, uuid),
  app.pair_accept(uuid), app.pair_end(uuid), app.owner_fill(), app.sdr_fill() from public, anon;
grant execute on function app.pair_active(uuid, uuid), app.pair_request(uuid, uuid), app.pair_accept(uuid), app.pair_end(uuid) to authenticated;
commit;
-- ---------- SHARED: accounts ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
alter table public.accounts add column if not exists sdr_uid uuid not null default 'b14d1605-c766-4684-9a5b-71ffcab6967b'::uuid;
alter table public.accounts alter column sdr_uid drop default;
alter table public.accounts add column if not exists ae_uid uuid;
create index if not exists accounts_sdr_uid_idx on public.accounts (sdr_uid);
create index if not exists accounts_ae_uid_idx on public.accounts (ae_uid) where ae_uid is not null;
do $$ begin if not exists (select 1 from pg_trigger where tgname = 'sdr_fill' and tgrelid = 'public.accounts'::regclass) then
  create trigger sdr_fill before insert on public.accounts for each row execute function app.sdr_fill(); end if; end $$;
drop policy if exists owner_all on public.accounts;
create policy owner_all on public.accounts as permissive for all to authenticated
  using (((sdr_uid = ( SELECT auth.uid() AS uid)) AND (( SELECT is_owner() AS is_owner) OR ( SELECT app.is_member(workspace_id) AS is_member))))
  with check (((sdr_uid = ( SELECT auth.uid() AS uid)) AND (( SELECT is_owner() AS is_owner) OR ( SELECT app.is_member(workspace_id) AS is_member))));
drop policy if exists ae_read on public.accounts;
create policy ae_read on public.accounts as permissive for select to authenticated
  using (((ae_uid = ( SELECT auth.uid() AS uid)) AND ( SELECT app.pair_active(accounts.workspace_id, accounts.sdr_uid) AS pair_active)));
commit;
-- ---------- helpers that read accounts.sdr_uid / ae_uid (after the accounts columns exist) ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
-- caller may read this account as its paired AE
create or replace function app.ae_sees_account(acc uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.accounts a where a.id = acc and a.ae_uid = auth.uid() and app.pair_active(a.workspace_id, a.sdr_uid))
$$;
-- caller is the account's SDR (used to stop attaching people/research to someone else's account)
create or replace function app.owns_account(acc uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.accounts a where a.id = acc and a.sdr_uid = auth.uid())
$$;

-- what a paired AE may see of the SDR's people: no DM text, notes, research, context or extra
create or replace function app.shared_people()
 returns table (id text, account_id uuid, company text, name text, title text, linkedin_url text, role text, stage text,
                stage_changed_at timestamptz, replied timestamptz, meeting timestamptz)
 language sql stable security definer set search_path = '' as $$
  select p.id, p.account_id, p.company, p.name, p.title, p.linkedin_url, p.role, p.stage, p.stage_changed_at,
         p.replied::timestamptz, p.meeting::timestamptz
    from public.people p
   where p.account_id is not null and p.deleted_at is null and app.ae_sees_account(p.account_id)
$$;

revoke all on function app.ae_sees_account(uuid), app.owns_account(uuid), app.shared_people() from public, anon;
grant execute on function app.ae_sees_account(uuid), app.owns_account(uuid), app.shared_people() to authenticated;
commit;
