-- ---------- ari_pref / ari_push_ack: owner_uid = caller for signed-in callers (signatures, owner, ACL unchanged) ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
create or replace function public.ari_pref(p_key text, p_default jsonb default null::jsonb)
 returns jsonb
 language sql
 stable security definer
 set search_path to 'public'
as $function$
  select coalesce((select p.value from public.ari_prefs p
                    where p.key = p_key
                      and (coalesce(auth.role(), '') not in ('authenticated', 'anon')
                           or (p.owner_uid = auth.uid() and (public.is_owner() or app.is_member(p.workspace_id))))), p_default);
$function$;
create or replace function public.ari_push_ack(p_endpoint text, p_tag text default null::text)
 returns void
 language sql
 security definer
 set search_path to 'public'
as $function$
  update public.push_subscriptions set last_rx_at = now(), last_rx_tag = left(p_tag, 64)
   where endpoint = p_endpoint and revoked_at is null
     and (coalesce(auth.role(), '') not in ('authenticated', 'anon')
          or (owner_uid = auth.uid() and (public.is_owner() or app.is_member(workspace_id))));
$function$;
commit;

-- ---------- ledger, after the end state is checked ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
do $$ declare n int; begin
  select count(*) into n from information_schema.columns where table_schema = 'public' and column_name = 'owner_uid'
     and is_nullable = 'NO' and table_name = any(array['people', 'account_briefs', 'account_stage_history', 'research', 'app_changes', 'app_config', 'app_usage', 'ari_notes', 'ari_prefs', 'attachments', 'book', 'brief', 'copy_guidance', 'decisions', 'draft_edits', 'draft_tags', 'emails', 'events', 'hygiene_findings', 'log_entries', 'messages', 'notifications', 'ops', 'plays', 'push_subscriptions', 'push_tokens', 'queue', 'replies', 'scan_heartbeat', 'sent_messages', 'targets', 'task_events', 'tasks', 'threads']);
  if n <> 34 then raise exception '0045: owner_uid on % of 34 tables', n; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'accounts' and column_name = 'sdr_uid' and is_nullable = 'NO') then
    raise exception '0045: accounts.sdr_uid missing'; end if;
  select count(*) into n from pg_policies where schemaname = 'public' and roles = '{authenticated}'
     and (coalesce(qual, '') || coalesce(with_check, '')) like '%is_member%'
     and (coalesce(qual, '') || coalesce(with_check, '')) not like '%owner_uid%' and (coalesce(qual, '') || coalesce(with_check, '')) not like '%sdr_uid%';
  if n <> 0 then raise exception '0045: % workspace policies still lack the owner clause', n; end if;
  select count(*) into n from pg_policies where schemaname = 'public' and policyname = 'ae_read';
  if n <> 4 then raise exception '0045: expected 4 ae_read policies, found %', n; end if;
  if has_table_privilege('authenticated', 'app.pairings', 'insert') or has_table_privilege('authenticated', 'app.pairings', 'update')
     or has_table_privilege('authenticated', 'app.memberships', 'insert') or has_table_privilege('authenticated', 'app.memberships', 'update') then
    raise exception '0045: authenticated can write pairings/memberships directly'; end if;
end $$;
insert into supabase_migrations.schema_migrations(version, name) values ('0045', 'pair_visibility') on conflict do nothing;
commit;
